/* Question-owned branching authoring. Uses ordinary condition nodes in the saved graph. */
function qrConfigKey(ref){return ({weight:'reporting_weight_35',rate:'valuation_fattening_rate'})[ref]||ref;}
function qrUnit(unit){const value=String(unit||'').trim().replace('₹/','INR/');return value==='%'?'percent':value;}
function qrConfigs(module=current){
 if(typeof configValuesForModule!=='function')return {};
 return Object.fromEntries(configValuesForModule(module).filter(i=>['number','integer','currency','weight','quantity','percent'].includes(i.valueType)&&typeof i.value==='number'&&Number.isFinite(i.value)).map(i=>[i.configKey,{...i,label:i.sourceOwner+' · '+i.name}]));
}
function qrResolve(c,q,module=current){const choices=qrConfigs(module),ref=String(c.valueRef||'').startsWith('config:')?Object.values(choices).find(i=>i.id===c.valueRef.slice(7)):choices[qrConfigKey(c.valueRef)];return ref&&q?.answer==='Number'&&qrUnit(q.unit)===qrUnit(ref.unit)&&!['between','answered','unanswered'].includes(c.op)?ref:null;}
function qrPinReference(c,q,module=current){const ref=qrResolve(c,q,module);if(!ref)throw new Error('Choose a compatible shared configuration value; its source may be missing, archived, unlinked or use a different unit.');c.valueRef='config:'+ref.id;c.value=String(ref.value);c.configSnapshot={id:ref.id,configKey:ref.configKey,revision:ref.revision,value:ref.value,unit:ref.unit,valueType:ref.valueType,sourceOwner:ref.sourceOwner};return c.configSnapshot;}
function qrOwned(q){const map=new Map(sop().nodes.map(n=>[n.id,n])),rows=[],seen=new Set();let n=map.get(q.next);while(n?.ruleOwner===q.id&&!seen.has(n.id)){rows.push(n);seen.add(n.id);n=map.get(n.no)}return rows}
function qrCommit(fn){if(!canEdit())return;const before=JSON.stringify(sop().nodes);fn();persist();canvasRemember(before);drawGraph();inspect()}
function qrAdd(id){qrCommit(()=>{const q=sop().nodes.find(n=>n.id===id),rows=qrOwned(q);if(!rows.length)q.ruleFallback=q.next;const n={id:'rule-'+crypto.randomUUID(),type:'condition',ruleOwner:id,source:id,label:'Answer branch '+(rows.length+1),op:q.answer==='Number'?'>':'=',value:q.answer==='Yes / No'?'Yes':'',match:'all',clauses:[],yes:q.ruleFallback,no:q.ruleFallback,x:q.x+330,y:q.y+170+rows.length*190};sop().nodes.push(n);if(rows.length)rows.at(-1).no=n.id;else q.next=n.id;});}
function qrEdit(id,key,value,ci=-1){qrCommit(()=>{const n=sop().nodes.find(n=>n.id===id),c=ci<0?n:n.clauses[ci];if(['yes','no'].includes(key)&&!canvasCanConnect(sop().nodes,id,key,value)){toast('Choose a later step; this would create a loop.');return;}c[key]=value;if(key==='source'){const q=sop().nodes.find(a=>a.id===value);c.op=q?.answer==='Number'?'>':'=';c.value='';delete c.valueRef;}if(key==='op'&&['between','answered','unanswered'].includes(value))delete c.valueRef;if(key==='valueRef'){c.valueRef=value?qrConfigKey(value):'';const q=sop().nodes.find(a=>a.id===c.source),ref=value?qrResolve(c,q):null;c.value=ref?String(ref.value):'';delete c.configSnapshot;}})}
function qrCheck(id){qrCommit(()=>{const n=sop().nodes.find(n=>n.id===id);n.clauses.push({source:n.source,op:'=',value:''})})}
function qrRemoveCheck(id,i){qrCommit(()=>sop().nodes.find(n=>n.id===id).clauses.splice(i,1))}
function qrRemove(id){qrCommit(()=>{const n=sop().nodes.find(n=>n.id===id);for(const a of sop().nodes)for(const p of canvasPorts(a))if(a[p.key]===id)a[p.key]=n.no;sop().nodes=sop().nodes.filter(a=>a.id!==id)})}
function qrFallback(id,value){qrCommit(()=>{const q=sop().nodes.find(n=>n.id===id),old=q.ruleFallback;const rows=qrOwned(q);if(rows.length&&!canvasCanConnect(sop().nodes,rows.at(-1).id,'no',value)){toast('Choose a later step; this would create a loop.');return;}q.ruleFallback=value;if(rows.length)rows.at(-1).no=value})}
function qrDestination(id,value){if(value==='__question'){canvasInsertMenu(id,'yes');return}if(value==='__new'){modal('Create action for this outcome',`<label class="field">Action title<input id="qr-action-title" placeholder="Describe this outcome"></label><label class="field">Instruction for the operator<textarea id="qr-action-text" placeholder="What should the operator do?"></textarea></label><p class="muted">This creates an operator instruction. It does not execute an automatic system operation.</p><button class="primary" onclick="qrCreateAction('${id}')">Create & connect action</button>`);return}qrEdit(id,'yes',value)}
function qrCreateAction(id){const title=$('#qr-action-title').value.trim(),instruction=$('#qr-action-text').value.trim();if(!title||!instruction)return toast('Add an action title and instruction.');qrCommit(()=>{const r=sop().nodes.find(n=>n.id===id),q=sop().nodes.find(n=>n.id===r.ruleOwner),a={id:'action-'+crypto.randomUUID(),type:'action',label:title,instruction,action:'Instruction',next:q.ruleFallback,x:r.x+350,y:r.y};sop().nodes.push(a);r.yes=a.id});closeModal()}
function qrChoices(c,id,i){const q=sop().nodes.find(n=>n.id===c.source);if(c.valueRef)return '';const opts=q?.answer==='Yes / No'?['Yes','No'].map(v=>({value:v,label:v})):q?.answer==='Catalogue'?nodeCatalogue(q,current).map(v=>({value:v.id,label:v.name})):['Single choice','Multiple choice'].includes(q?.answer)?questionnaireOptions(q):null;return opts?`<select aria-label="Branch answer value" onchange="qrEdit('${id}','value',this.value,${i})"><option value="">Choose answer</option>${opts.map(o=>`<option value="${esc(o.value)}" ${String(c.value)===String(o.value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:`<input aria-label="Branch comparison value" placeholder="${c.op==='between'?'100..103':'Enter value'}" value="${esc(c.value??'')}" oninput="qrValueInput('${id}',this.value,${i})" onchange="drawGraph()">`}
function qrCheckHtml(c,n,i){const q=sop().nodes.find(a=>a.id===c.source),ops=q?.answer==='Number'?['=','!=','>','>=','<','<=','between','answered','unanswered']:['=','!=','contains','not_contains','answered','unanswered'];return `<div class="qr-check"><label class="checkrow"><input type="checkbox" ${c.negate?'checked':''} onchange="qrEdit('${n.id}','negate',this.checked,${i})">NOT (!)</label><select aria-label="Branch check answer" onchange="qrEdit('${n.id}','source',this.value,${i})">${sop().nodes.filter(a=>a.type==='question').map(a=>`<option value="${a.id}" ${a.id===c.source?'selected':''}>${esc(a.label)}</option>`).join('')}</select><select aria-label="Branch comparison" onchange="qrEdit('${n.id}','op',this.value,${i})">${ops.map(op=>`<option value="${esc(op)}" ${c.op===op?'selected':''}>${esc(op)} · ${ruleOperators[op]}</option>`).join('')}</select>${!['answered','unanswered'].includes(c.op)?`${q?.answer==='Number'?`<select aria-label="Compare with" onchange="qrEdit('${n.id}','valueRef',this.value,${i})"><option value="">A value I enter</option>${c.valueRef&&!qrResolve(c,q)?'<option selected disabled>Unavailable configuration · choose another</option>':''}${Object.entries(qrConfigs()).filter(([k,v])=>qrUnit(v.unit)===qrUnit(q.unit)&&c.op!=='between').map(([k,v])=>`<option value="config:${esc(v.id)}" ${qrResolve(c,q)?.id===v.id?'selected':''}>${esc(v.label)} (${v.value} ${esc(v.unit)})</option>`).join('')}</select>`:''}${qrChoices(c,n.id,i)}`:''}${i>=0?`<button class="ghost" onclick="qrRemoveCheck('${n.id}',${i})">Remove check</button>`:''}</div>`}
const qrInspectBase=inspect;inspect=function(){qrInspectBase();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!q||q.type!=='question'||!p)return;const old=p.querySelector('button[onclick^="generateQuestionBranches"]');if(old){let h=old.previousElementSibling;h?.remove();old.remove();p.querySelectorAll('h3').forEach(h=>{if(h.textContent==='Answer paths')h.remove()})}const rows=qrOwned(q),section=document.createElement('section');section.className='qr-panel';section.innerHTML=`<h2>Based on the answer</h2><p class="muted">First matching branch wins, from top to bottom. Each branch becomes a path in the flow.</p>${rows.map((n,i)=>`<article class="qr-branch"><div class="qr-heading"><b>IF · Branch ${i+1}</b><button class="ghost" onclick="qrRemove('${n.id}')">Remove</button></div>${qrCheckHtml(n,n,-1)}${n.clauses?.length?`<select aria-label="Combine checks" onchange="qrEdit('${n.id}','match',this.value)"><option value="all" ${n.match!=='any'?'selected':''}>ALL checks · AND</option><option value="any" ${n.match==='any'?'selected':''}>ANY check · OR</option></select>`:''}${(n.clauses||[]).map((c,j)=>qrCheckHtml(c,n,j)).join('')}<button class="ghost" onclick="qrCheck('${n.id}')">+ AND / OR check</button><label class="field">THEN go to<select aria-label="Branch destination" onchange="qrDestination('${n.id}',this.value)"><option value="${q.ruleFallback}">Continue on default path</option><option value="__new">+ Create custom action…</option><option value="__question">+ Create question on this path…</option>${sop().nodes.filter(a=>a.id!==q.id&&a.type!=='start'&&!a.ruleOwner).map(a=>`<option value="${a.id}" ${n.yes===a.id?'selected':''}>${esc(a.label)}</option>`).join('')}</select></label></article>`).join('')}<button class="primary" onclick="qrAdd('${q.id}')">+ Add branch · > < = ≠</button>${rows.length?`<label class="field qr-fallback">OTHERWISE / unanswered<select aria-label="Otherwise destination" onchange="qrFallback('${q.id}',this.value)">${sop().nodes.filter(a=>a.id!==q.id&&a.type!=='start'&&!a.ruleOwner).map(a=>`<option value="${a.id}" ${q.ruleFallback===a.id?'selected':''}>${esc(a.label)}</option>`).join('')}</select></label>`:''}`;const anchor=p.querySelector('.actions')||p.querySelector('.question-settings');p.insertBefore(section,anchor||null);if(!canEdit())section.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);for(const name of ['Minimum answer','Maximum answer']){const el=p.querySelector(`[aria-label="${name}"]`);if(el){el.title='Answer validation only: restricts allowed input, does not choose a branch.';const label=el.closest('label');if(label)label.dataset.validation='true'}}};
function qrEvaluate(n,answers,nodes=sop().nodes){const checks=[n,...n.clauses||[]].map(c=>{let a=answers[c.source];const q=nodes.find(q=>q.id===c.source);if(q?.answer==='Number'&&a!==undefined&&a!==null&&a!==''&&!['answered','unanswered'].includes(c.op)){if(Array.isArray(a)||!Number.isFinite(Number(a)))return false;a=Number(a);}const present=compare(a,'answered','');if(!present&&!['answered','unanswered'].includes(c.op))return false;const result=compare(a,c.op,c.value);return c.negate?!result:result});return n.match==='any'?checks.some(Boolean):checks.every(Boolean)}
const qrSimBase=renderSim;renderSim=function(){const n=sim?.nodes?.find(a=>a.id===sim.id);if(n?.type==='condition'&&(n.ruleOwner||[n,...n.clauses||[]].some(c=>c.negate))){const yes=qrEvaluate(n,sim.answers,sim.nodes);sim.path.push(n.label+' → '+(yes?'Match':'Otherwise'));sim.id=yes?n.yes:n.no;return renderSim()}return qrSimBase()};
const qrPagePathBase=pageQuestionPath;pageQuestionPath=function(definition,answers){const map=new Map(definition.nodes.map(n=>[n.id,n])),seen=new Set(),questions=[];let id=definition.entryNodeId;while(id&&!seen.has(id)){seen.add(id);const n=map.get(id);if(!n)break;if(n.type==='question'){questions.push(n);id=n.next}else if(n.type==='condition')id=qrEvaluate(n,answers,definition.nodes)?n.yes:n.no;else if(n.type==='end')break;else id=n.next}return questions};
const qrCompileBase=compileWorkflow;compileWorkflow=function(s,m=current,v=s.version||0){const copy=structuredClone(s),references={};for(const n of copy.nodes)if(n.type==='condition')for(const c of [n,...n.clauses||[]])if(c.valueRef){const snapshot=qrPinReference(c,copy.nodes.find(q=>q.id===c.source),m);references[snapshot.configKey]=snapshot;}const result=qrCompileBase(copy,m,v);result.configReferences=references;return result};
function qrTestOptions(q){
 if(q.answer==='Yes / No')return ['Yes','No'].map(value=>({value,label:value}));
 if(q.answer==='Catalogue')return nodeCatalogue(q,current).map(item=>({value:item.id,label:item.name}));
 if(['Single choice','Multiple choice'].includes(q.answer))return questionnaireOptions(q);
 return null;
}
function qrTestField(q){
 const options=qrTestOptions(q),id=esc(q.id),title=esc(q.label)+(q.unit?' · '+esc(q.unit):'');
 if(q.answer==='Multiple choice')return `<fieldset class="field"><legend>${title}</legend>${options.map(o=>`<label class="checkrow"><input data-qr-test="${id}" type="checkbox" value="${esc(o.value)}">${esc(o.label)}</label>`).join('')}<small>Select no choices to test unanswered.</small></fieldset>`;
 if(options)return `<label class="field">${title}<select data-qr-test="${id}"><option value="">Unanswered</option>${options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select></label>`;
 return `<label class="field">${title}<input data-qr-test="${id}" type="${q.answer==='Number'?'number':q.answer==='Date'?'date':'text'}" ${q.answer==='Number'?'step="any"':''} placeholder="Leave empty to test unanswered"></label>`;
}
function qrTest(id){const q=sop().nodes.find(n=>n.id===id),rows=qrOwned(q),sources=[...new Set(rows.flatMap(n=>[n,...n.clauses||[]].map(c=>c.source)))];modal('Test answer branches',`<p>Check these rules without completing the SOP. No actions run.</p>${sources.map(id=>qrTestField(sop().nodes.find(n=>n.id===id))).join('')}<button class="primary" onclick="qrTestRun('${id}')">Check outcome</button><div id="qr-test-result" role="status"></div>`)}
function qrTestRun(id){
 const q=sop().nodes.find(n=>n.id===id),answers={};let invalid='';
 document.querySelectorAll('[data-qr-test]').forEach(el=>{
  const source=sop().nodes.find(n=>n.id===el.dataset.qrTest);if(!source){invalid='This answer source is no longer available.';return;}
  const options=qrTestOptions(source);
  if(source.answer==='Multiple choice'){
   if(!el.checked)return;
   if(!options.some(o=>String(o.value)===el.value)){invalid='Choose an available option for '+source.label+'.';return;}
   (answers[source.id]??=[]).push(el.value);return;
  }
  if(source.answer==='Number'&&(el.validity?.badInput||(el.value!==''&&!Number.isFinite(Number(el.value)))))invalid='Enter a valid number for '+(source.label||'the question')+'.';
  if(el.value!==''&&options&&!options.some(o=>String(o.value)===el.value))invalid='Choose an available option for '+source.label+'.';
  if(el.value!=='')answers[source.id]=source.answer==='Number'?Number(el.value):el.value;
 });
 if(invalid){$('#qr-test-result').textContent=invalid;return;}
 const rows=structuredClone(qrOwned(q));for(const n of rows)for(const c of [n,...n.clauses||[]])if(c.valueRef){try{qrPinReference(c,sop().nodes.find(q=>q.id===c.source));}catch(error){$('#qr-test-result').textContent=error.message;return;}}
 const n=rows.find(n=>qrEvaluate(n,answers)),dest=sop().nodes.find(a=>a.id===(n?n.yes:q.ruleFallback));$('#qr-test-result').textContent=(n?'Matched '+n.label:'Otherwise / unanswered')+' → '+(dest?.label||'Choose destination');
}
function qrAdopt(id){qrCommit(()=>{const q=sop().nodes.find(n=>n.id===id),map=new Map(sop().nodes.map(n=>[n.id,n]));let n=map.get(q.next),seen=new Set();while(n?.type==='condition'&&n.source===id&&!seen.has(n.id)){seen.add(n.id);n.ruleOwner=id;n.clauses??=[];n=map.get(n.no)}q.ruleFallback=n?.id||''})}
const qrFinalInspectBase=inspect;inspect=function(){qrFinalInspectBase();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!q||q.type!=='question'||!p)return;const panel=p.querySelector('.qr-panel'),rows=qrOwned(q),next=sop().nodes.find(n=>n.id===q.next);if(panel){if(rows.length)panel.insertAdjacentHTML('beforeend',`<button style="margin-top:12px;width:100%" onclick="qrTest('${q.id}')">▷ Test these branches</button>`);else if(next?.type==='condition'&&next.source===q.id)panel.insertAdjacentHTML('afterbegin',`<div class="notice">This question already has a condition: <b>${esc(next.label)}</b><button onclick="qrAdopt('${q.id}')" ${canEdit()?'':'disabled'}>Edit existing answer branches here</button></div>`)}if(q.answer==='Number'){const min=p.querySelector('[aria-label="Minimum answer"]'),max=p.querySelector('[aria-label="Maximum answer"]');if(min&&max){const details=document.createElement('details');details.className='qr-validation';details.innerHTML='<summary>Answer validation · optional input limits</summary><p class="muted">Only limits which numbers can be entered. Use branches above to decide what happens.</p>';for(const el of [min,max]){const label=el.closest('label');if(label)details.append(label)}panel?.after(details);if(q.min!==null&&q.max!==null&&Number(q.min)>Number(q.max)){details.open=true;details.insertAdjacentHTML('beforeend','<p class="error">Minimum is greater than maximum. Correct or clear these input limits.</p>')}}}};
const qrValidateBase=validateWorkflow;validateWorkflow=function(s,m=current){const errors=qrValidateBase(s,m);for(const n of s.nodes.filter(n=>n.type==='condition'))for(const c of [n,...n.clauses||[]])if(c.valueRef){const q=s.nodes.find(a=>a.id===c.source);if(!qrResolve(c,q,m))errors.push(n.label+': choose a compatible shared configuration value.')}return [...new Set(errors)]};
function qrValueInput(id,value,i=-1){if(!canEdit())return;const n=sop().nodes.find(n=>n.id===id),c=i<0?n:n.clauses[i],before=JSON.stringify(sop().nodes);c.value=value;persist();canvasRemember(before)}
function qrManagedPort(id,key){const n=sop().nodes.find(n=>n.id===id);return !!(n?.ruleOwner&&key==='no'&&sop().nodes.some(a=>a.id===n.no&&a.ruleOwner===n.ruleOwner)||n?.type==='question'&&key==='next'&&qrOwned(n).length)}
function qrManagedNotice(id){const n=sop().nodes.find(n=>n.id===id);selected=n?.ruleOwner||id;inspect();toast('Edit ordered branches on the question. Matching action paths can be connected on the canvas.')}
const qrCanvasConnectBase=canvasConnect;canvasConnect=function(id,key,target){if(qrManagedPort(id,key)){canvasCancelWire();return qrManagedNotice(id)}const from=sop().nodes.find(a=>a.id===id),owner=from?.ruleOwner&&key==='no'?sop().nodes.find(a=>a.id===from.ruleOwner):null;const result=qrCanvasConnectBase(id,key,target);if(owner){owner.ruleFallback=from.no;persist()}return result};
const qrDeleteEdgeBase=canvasDeleteEdge;canvasDeleteEdge=function(){if(canvasEdge&&qrManagedPort(canvasEdge.id,canvasEdge.key))return qrManagedNotice(canvasEdge.id);const edge=canvasEdge&&{...canvasEdge},from=edge&&sop().nodes.find(a=>a.id===edge.id),owner=from?.ruleOwner&&edge.key==='no'?sop().nodes.find(a=>a.id===from.ruleOwner):null;const result=qrDeleteEdgeBase();if(owner){owner.ruleFallback=from.no;persist()}return result};
const qrInsertBase=canvasInsert;canvasInsert=function(id,key,type){if(qrManagedPort(id,key)){closeModal();return qrManagedNotice(id)}const from=sop().nodes.find(a=>a.id===id),owner=from?.ruleOwner&&key==='no'?sop().nodes.find(a=>a.id===from.ruleOwner):null;const result=qrInsertBase(id,key,type);if(owner){owner.ruleFallback=from.no;persist()}return result};
const qrRemoveNodeBase=canvasRemoveNode;canvasRemoveNode=function(id,key){const n=sop().nodes.find(n=>n.id===id);if(n?.ruleOwner){selected=n.ruleOwner;qrRemove(id);closeModal();return}const replacement=n?.[key]||'';const result=qrRemoveNodeBase(id,key);if(!sop().nodes.some(a=>a.id===id)){for(const q of sop().nodes)if(q.ruleFallback===id)q.ruleFallback=replacement;persist()}return result};
const qrTypedInsertBase=insertTypedQuestion;insertTypedQuestion=function(id,key,type){if(qrManagedPort(id,key)){closeModal();qrManagedNotice(id);return false}return qrTypedInsertBase(id,key,type)};
const qrDrawBase=drawGraph;drawGraph=function(){qrDrawBase();document.querySelectorAll('[data-plus-id]').forEach(el=>{if(qrManagedPort(el.dataset.plusId,el.dataset.plusKey)){el.textContent='⋯';el.setAttribute('aria-label','Edit answer branches');el.title='Edit answer branches';el.onclick=()=>{const n=sop().nodes.find(n=>n.id===el.dataset.plusId);selected=n.ruleOwner||n.id;inspect();$('#inspector .qr-panel')?.scrollIntoView({block:'nearest'})}}})};
const qrCompactInspectBase=inspect;inspect=function(){qrCompactInspectBase();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!q||q.type!=='question'||!p||!qrOwned(q).length)return;const type=p.querySelector('[aria-label="Answer type"]'),unit=p.querySelector('[aria-label="Unit"]'),panel=p.querySelector('.qr-panel');if(type&&panel){const details=document.createElement('details');details.className='qr-answer-settings';details.innerHTML=`<summary>${esc(q.answer)}${q.unit?' · '+esc(q.unit):''} — Answer settings</summary>`;details.append(type.closest('label'));if(unit)details.append(unit.closest('label'));panel.before(details);p.querySelectorAll('.inputrow').forEach(row=>{if(!row.querySelector('input,select,textarea'))row.remove()})}p.classList.add('qr-compact-inspector')};

function qrEnsureUnitOptions(select,module=current){
 if(!select)return;const units=[...new Set(['INR/kg','g/head','percent',...Object.values(qrConfigs(module)).map(i=>i.unit)])];
 for(const unit of units)if(!Array.from(select.options).some(o=>qrUnit(o.value)===qrUnit(unit)))select.insertAdjacentHTML('beforeend',`<option value="${esc(unit)}">${esc(unit==='percent'?'%':unit)}</option>`);
}
const qrTypedUnitsInspect=inspect;
inspect=function(){qrTypedUnitsInspect();const q=sop().nodes.find(n=>n.id===selected);if(q?.answer!=='Number')return;const select=$('#inspector')?.querySelector('[aria-label="Unit"]');qrEnsureUnitOptions(select);if(select&&Array.from(select.options).some(o=>o.value===q.unit))select.value=q.unit;qrWireUnitRefresh(select);};
function qrWireUnitRefresh(select){if(!select||select.dataset?.qrRefreshBound)return;const previous=select.onchange;select.onchange=function(event){if(previous)previous.call(this,event);inspect();};if(select.dataset)select.dataset.qrRefreshBound='true';}

// The direct decision editor and question-owned editor share reference semantics.
const qrLiteralEditBase=editNode;
editNode=function(key,value,refresh=false){const n=sop().nodes.find(n=>n.id===selected);if(canEdit()&&n?.type==='condition'&&['value','source','op'].includes(key)){const wasLinked=!!n.valueRef;delete n.valueRef;delete n.configSnapshot;if(wasLinked){const control=document.querySelector('[aria-label="Check 1 configuration"]');if(control)control.value='';}}return qrLiteralEditBase(key,value,refresh);};
const qrLiteralClauseBase=ruleClause;
ruleClause=function(index,key,value){const n=sop().nodes.find(n=>n.id===selected),c=n?.clauses?.[index];if(canEdit()&&c&&['value','source','op'].includes(key)){delete c.valueRef;delete c.configSnapshot;}return qrLiteralClauseBase(index,key,value);};
const qrDirectReferenceInspect=inspect;
inspect=function(){qrDirectReferenceInspect();const n=sop().nodes.find(n=>n.id===selected),panel=$('#inspector');if(n?.type!=='condition'||!panel)return;const html=[n,...(n.clauses||[])].map((c,index)=>{const q=sop().nodes.find(q=>q.id===c.source);if(q?.answer!=='Number'||['between','answered','unanswered'].includes(c.op))return '';const ref=qrResolve(c,q),options=Object.values(qrConfigs()).filter(i=>qrUnit(i.unit)===qrUnit(q.unit));return `<label class="field"><span>Check ${index+1} · Compare with</span><select aria-label="Check ${index+1} configuration" onchange="qrEdit('${n.id}','valueRef',this.value,${index-1})" ${canEdit()?'':'disabled'}><option value="">A value I enter</option>${c.valueRef&&!ref?'<option selected disabled>Unavailable configuration</option>':''}${options.map(i=>`<option value="config:${esc(i.id)}" ${ref?.id===i.id?'selected':''}>${esc(i.name)} · ${i.value} ${esc(i.unit)}</option>`).join('')}</select>${c.valueRef?'<small>Editing the literal value, source answer or operator switches to an entered value.</small>':''}</label>`;}).join('');if(html)panel.insertAdjacentHTML('beforeend','<section class="question-settings"><h3>Configuration references</h3>'+html+'</section>');};
